#!/usr/bin/env python3
"""Build Task 13 decision package from the verified prior audit."""
from pathlib import Path
from datetime import datetime, timezone
import csv, hashlib, shutil

PROJECT = Path(__file__).resolve().parents[2]
PRIOR = PROJECT / 'results/ultimate_execution_20261022T180431Z'
STAMP = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')
OUT = PROJECT / 'results' / f'task13_research_opportunity_{STAMP}'
OUT.mkdir(parents=True, exist_ok=False)

def write(name, content):
    (OUT / name).write_text(content.rstrip() + '\n', encoding='utf-8')

def tsv(name, header, rows):
    with (OUT/name).open('w', encoding='utf-8', newline='') as f:
        w=csv.writer(f, delimiter='\t', lineterminator='\n')
        w.writerow(header); w.writerows(rows)

def read_tsv(path):
    with path.open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f, delimiter='\t'))

ids=['PGLA1542300','PGLA1557868','PGLA1564064','PGLA1457537','PGLA1545539']
src=read_tsv(PRIOR/'five_sv_updated_evidence.tsv')
by={r['candidate_id']:r for r in src}
assert set(ids)==set(by) and len(src)==5
fields=['candidate_id','definition_class','source_ID','reference_name','reference_sequence_accession','chromosome','reported_position','coordinate_convention','SV_label','start_breakpoint','end_breakpoint','length_bp','REF_allele','ALT_or_inserted_sequence','deleted_sequence','flanking_sequence','graph_record_ID','accession_presence_absence_matrix','sequence_evidence','other_trait_GWAS_catalogued','strongest_trait_record','strongest_minus_log10P','local_carriers_n20','local_hom_ref_n20','local_missing_n20','direct_DMY_evidence','climate_association_evidence','independent_biological_validation','sources_checked','validation_status','DM_association_status']
tsv('sv_recovery_results.tsv',fields,[[r.get(k,'') for k in fields] for r in (by[i] for i in ids)])

write('sv_recovery_limitations.md', '''# SV recovery limitations\n\nAll five PGLA IDs were verified as rows in Yan et al. 2023 Supplementary Table S19 and in the prior local MilletDB cache. The rows provide PI537069-namespace chromosome, reported position and INS/DEL label, plus GWAS context for non-downy-mildew traits. They do not provide candidate-specific breakpoints, event length, allele sequence, flanking sequence, graph record, or accession-level PAV calls. The published methods describe a general PAV/INS/DEL framework; that does not resolve an individual candidate event.\n\nThe five reported records are therefore **association-table markers**, not sequence-resolved SV alleles. A coordinate and INS/DEL label are not sufficient to infer event identity, exact cohort genotype, or equivalence between PI537069, 843B and updated Tift. No coordinate-only liftover was treated as proof. The 20-accession historical matrix is descriptive and not an authoritative event-call resource; its counts cannot be transferred to the 2026 cohort. PGLA1557868 had zero carriers in that 20-sample matrix, which means only that the old matrix cannot test it.\n\n**Minimum missing dependency:** an authoritative event-level record keyed to each VariationID that includes assembly/version and event allele/breakpoints or sequence, plus a PAV/genotype matrix with accession identifiers and a documented crosswalk to the 2026 cohort. If only a graph path or reference coordinates are supplied, sequence-supported alignment is still required before cross-assembly identity can be claimed.\n\nPrior search coverage included Yan S19, local candidate/cache tables, the paper and data-availability materials, and prior targeted-retrieval assessment. MilletDB service/API retrieval was previously unavailable; no documented targeted endpoint or indexed record was established. Do not repeat broad searches or download the full VCFs absent a new authoritative index/endpoint.\n''')

write('coordinate_provenance_audit.md', '''# Coordinate provenance audit\n\nThe prior metadata audit found coordinates for 148 of 231 sequenced accessions: 145 distinct coordinate pairs, across 20 countries. Three coordinate pairs were each shared by two accessions. Ninety-three of the 148 coordinate-bearing accessions were assigned to Senegal; 83 sequenced accessions lacked coordinates. Observed bounds were latitude −24.379999 to 19.069999 and longitude −17.450001 to 38.009998.\n\nThe metadata do **not** establish whether a point is the accession's original collection locality, a reported origin locality, a program/administrative centroid, or another geocoding product. They also provide no stated coordinate precision, positional uncertainty, geocoding method, or reference date. Numeric decimal precision is not evidence of geographic accuracy. No independent accession-level source was recovered in the audited package to validate those fields.\n\nAccordingly, the coordinates cannot yet be interpreted as long-term selective environments. The Senegal concentration risks spatial clustering and confounding with ancestry; repeated points are not independent environments. Even a small climate extraction is deferred because coordinate meaning is unresolved and genotype PCs/kinship are unavailable. Disease-trial sites in Senegal are measurement environments and must not be substituted for accession-origin climate.\n\n**Resolution needed:** a source data dictionary or accession-level provenance statement, original locality/coordinate source and uncertainty, and a verified identifier join. Then inspect duplicates, country/locality consistency, spatial clustering and outliers before sampling climate grids.\n''')

tsv('climate_variable_plan.tsv',['priority','variable','interpretation','source_and_period','resolution_plan','use_condition','status'],[
 ['Primary','BIO1','Annual mean temperature','WorldClim 2.1, 1970–2000','Prefer 2.5 arc-min or coarser if positional uncertainty warrants; grid resolution cannot repair uncertain coordinates','Only after origin-coordinate provenance and sample joins are validated','Not extracted'],
 ['Primary','BIO4','Temperature seasonality','WorldClim 2.1, 1970–2000','Same as above','Assess collinearity and spatial structure before modeling','Not extracted'],
 ['Primary','BIO5','Maximum temperature of warmest month','WorldClim 2.1, 1970–2000','Same as above','Potential heat exposure proxy; not a direct heat-tolerance phenotype','Not extracted'],
 ['Primary','BIO12','Annual precipitation','WorldClim 2.1, 1970–2000','Same as above','Potential water-availability proxy; not drought response','Not extracted'],
 ['Primary','BIO15','Precipitation seasonality','WorldClim 2.1, 1970–2000','Same as above','Use only if accessions have meaningful origin coordinates','Not extracted'],
 ['Secondary','BIO6','Minimum temperature of coldest month','WorldClim 2.1, 1970–2000','Same as above','Include only with a priori rationale for pearl millet environments','Not extracted'],
 ['Secondary','BIO16','Precipitation of wettest quarter','WorldClim 2.1, 1970–2000','Same as above','Consider alongside BIO12; avoid redundant predictors','Not extracted'],
 ['Secondary','BIO17','Precipitation of driest quarter','WorldClim 2.1, 1970–2000','Same as above','Potential seasonal dryness proxy; not proof of adaptation','Not extracted'],
 ['Alternative','BIO1/BIO4/BIO5/BIO12/BIO15','Matched bioclimatic summaries','CHELSA v2.1, 1981–2010','Kilometer-scale product; select only one climate product for primary analysis','Sensitivity analysis only after provenance and genetic model gates','Not extracted']])

write('climate_feasibility_decision.md', '''# Climate feasibility decision\n\n**Decision: no-go for extraction or genotype–environment association in this task.** WorldClim 2.1 (1970–2000 normals) and CHELSA v2.1 (1981–2010 climatologies) are suitable candidate sources for long-term climate summaries, but the accession-coordinate meaning and uncertainty are undocumented. The audited overlap is 148/231 with coordinates, with 93/148 assigned to Senegal and only 145 unique point pairs. This is substantial geographic imbalance and possible spatial dependence.\n\nNo climate values have been extracted. No genotype matrix, population PCs, kinship matrix, or validated accession-level SV calls are locally available; the only retrieved VCF resources are two separate, very large, unindexed SNP callsets. A GEA with coordinates and unadjusted markers would confound ancestry and geography, and geographic correlation would not itself demonstrate adaptation. Trial-site disease measurements are not accession-origin climate.\n\nThe variable plan is a preregistered shortlist, not an analysis result. After provenance validation, choose one climate product and baseline, quantify coordinate uncertainty and spatial clustering, then determine matched genetic sample size and ancestry controls before deciding if a pilot is justified. Sources: [WorldClim 2.1](https://www.worldclim.org/data/worldclim21.html); [CHELSA v2.1 bioclim](https://www.chelsa-climate.org/datasets/chelsa_bioclim).''')

write('alternative_genetic_analysis_assessment.md', '''# Alternative disease-genetics analysis assessment\n\n## Reconciled phenotype resource\n\nThe audited workbook contains 3,456 plot records for 288 accessions (12 records per accession across four Senegal disease-trial sites, three replicates and nine blocks per replicate). Exact GID matching to the WGS run metadata retains 231 accessions and 2,772 plot rows; 57 accessions/684 rows are phenotype-only and should not be silently included in genotype analyses. No missing or out-of-range disease values or duplicate plot keys were found in the prior QC. The response is an infected/total plant ratio scaled 0–1, but numerator/denominator fields and denominator metadata are absent. These are replicated plot observations, not independent genotypes.\n\n## Existing genetic data and known markers\n\nThe prior inventory found no local cohort VCF, BCF, PLINK matrix, PCs or kinship. Two public filtered SNP callsets are listed at 32.43 GB (843B) and 41.42 GB (updated Tift), with no index listed; they are distinct reference builds, and the paper says indels were excluded. No derived SNP matrix or compatible marker-level genotype table was found. The five SV association IDs have no event-specific calls. Published DM QTL/marker results exist, but a defensible comparison requires exact marker/allele definitions, harmonized assembly, direct 2026 cohort genotypes and structure controls; those prerequisites are not met by the available summary evidence.\n\n## Value and limits of feasible work\n\nA descriptive phenotype characterization by site, accession, replication and distribution can be independently useful as a data/QC note or supporting analysis, but absent denominators it cannot recover binomial uncertainty, and absent cohort genotypes it is not an SV association or replication test. Repeated tests on the same accessions do not increase independent genetic sample size above 231. The prior best-case power gate for a scan of 22.2M markers across four sites requires very large standardized effects and is optimistic; no scan should be run to harvest nominal p-values.\n\n**Assessment:** no alternative disease-genetics association is currently ready without substantial genotype retrieval and QC. If a later study is pursued, use one reference build, validate its sample IDs and variants, create PCs/kinship, inspect phenotype denominator provenance, and prespecify a repeated-measures model. A targeted known-marker replication is only preferable if exact published marker alleles can be harmonized and retrieved without whole-callset processing. The local evidence does not yet meet that condition.''')

write('updated_literature_gap.md', '''# Updated literature gap and contribution\n\nPearl millet downy mildew genetics is not an untouched area. Prior studies report pathogen/pathotype-dependent resistance QTL (Jones et al. 1995; Saritha et al. 2017; Chelpuri et al. 2019), marker-assisted introgression of resistance loci (Taunk et al. 2018), and downy-mildew resistance marker–trait associations in a breeding panel (Ramu et al. 2023). Yan et al. (2023) established a pangenome/PAV association framework, but these five IDs are recorded for other traits in S19 and have not been directly linked to downy mildew resistance in the audited sources. The 2026 Senegal multi-site cohort supplies a potentially useful phenotype resource but its public SNP files are large and not yet analyzed here.\n\nThe defensible gap is narrower: whether particular sequence-resolved pangenome SV alleles replicate or add value in a phenotyped, multi-environment pearl millet panel, with harmonized event calls, accession joins, ancestry control and pathotype-aware phenotypes. That question is currently unanswerable because exact SV alleles/calls and compatible cohort genotypes are missing; climate adaptation is separately blocked by coordinate provenance and genetics.\n\nThe current reconciliation and audit improve reproducibility, expose an exact 288-to-231 cohort distinction, clarify candidate evidence and prevent unsupported claims. On its own, however, an audit with no novel genetic association, resolved SV event, or validated environmental analysis is not a strong standalone original-research paper. It is best retained as a reproducibility/portfolio package and supporting methods/supplement. Do not claim a first DM GWAS, new resistance SV, or climate adaptation.\n\n### Core literature checked\n\n- Yan et al. 2023, pangenome and PAV association study: https://www.nature.com/articles/s41588-023-01302-4\n- Subedi et al. 2026, multi-site disease phenotype and genotype dataset: https://doi.org/10.1016/j.dib.2026.112746; source record https://zenodo.org/records/18602603\n- Jones et al. 1995, pathotype-dependent DM QTL: https://pubmed.ncbi.nlm.nih.gov/24169834/\n- Saritha et al. 2017, DM resistance QTL: https://oar.icrisat.org/10458/\n- Chelpuri et al. 2019, DM QTL across isolates: https://oar.icrisat.org/11314/1/chelpuri2019.pdf\n- Taunk et al. 2018, marker-assisted introgression: https://pubmed.ncbi.nlm.nih.gov/30555073/\n- Ramu et al. 2023, improved genomes and DM resistance MTAs: https://pmc.ncbi.nlm.nih.gov/articles/PMC10477261/\n''')

tsv('research_direction_comparison.tsv',['direction','scientific_value','required_inputs','current_feasibility','main_risk','publication_potential','decision'],[
 ['A. Continue exact SV validation','Could resolve whether prioritized PGLA markers are true sequence-resolved events and test replication','Authoritative candidate event records with assembly/alleles/breakpoints or sequence; accession PAV matrix; validated crosswalk to 2026 genotypes','Blocked: all five only have S19 marker coordinate/type; no event sequences or PAV matrix; no established targeted query','Coordinate-only harmonization or nearby-gene inference could misidentify events','Potentially strong after inputs are recovered and replicated; none ready now','Do not proceed to genotyping/association'],
 ['B. Climate-environment analysis','Could characterize environmental gradients or test GEA if origin environments, genotypes and ancestry are reliable','Coordinate provenance/uncertainty; matched genotypes; PCs/kinship; justified climate variables and spatial model','Blocked: 148/231 coords, origins unclear, 93/148 Senegal, no climate extraction/genetic structure','Spatial/ancestry confounding; GEA is not proof of adaptation','Not presently defensible','No-go pending provenance and genetics'],
 ['C. Targeted disease-genetics analysis','Could evaluate replication of established DM loci or run carefully gated exploratory analysis','Compatible published marker definitions/alleles/build; cohort genotype matrix; phenotype denominators; QC and structure','Not ready: no local SNP matrix; public 32/41 GB VCFs unindexed; 231 independent accessions; phenotype lacks denominators','Low power and false positives; no casual scan','Could become useful after marker/genotype/phenotype gates','Do not download full callsets yet'],
 ['D. Combine workstreams','Could integrate sequence-resolved SVs, DM phenotype and adaptation context','All A/B/C inputs plus prespecified integrated design','Not feasible; component evidence gates fail independently','Compounds confounding and overclaiming','Only after each component independently passes gates','Not recommended now'],
 ['E. Pause original discovery claims','Protects scientific accuracy while retaining audited candidate and cohort work','No new data needed to make the present decision; future work needs the dependencies above','Ready now','May delay original discovery claims; current package alone is not a strong discovery paper','Current deliverable is a supporting reproducibility/portfolio artifact','Recommended']])

write('task13_final_recommendation.md', '''# Task 13 final recommendation\n\n## Recommendation: E — Pause original discovery claims until additional data are obtained\n\nThe five SVs remain prioritized candidates with external non-DM GWAS context, not confirmed downy mildew resistance variants. Every candidate has only an association-table ID/coordinate and INS/DEL label in the audited source; no exact event sequence, breakpoint definition, accession-level PAV matrix, or validated 2026 cohort call was recovered. There is no scientifically valid way to infer those calls from the SNP VCFs or neighboring annotations.\n\nA climate analysis is also not ready: fewer than two-thirds of the sequenced cohort has coordinates, the coordinate source and uncertainty are undocumented, the points are geographically imbalanced, and no matched genetic structure data or climate values are available. A disease GWAS/replication is not ready either: no local compatible marker genotypes or ancestry controls exist, and the phenotype ratios lack denominator provenance. Prior DM QTL and GWAS already exist, so a “first association” claim is false.\n\n### Minimum missing inputs\n\n1. For SV work: an authoritative event-level record for each VariationID (assembly accession/version, breakpoints or sequence/alleles, event type/length) and an accession-level PAV/genotype matrix with a verified cohort crosswalk.\n2. For climate work: validated accession-origin coordinates plus source, precision and uncertainty; matched genotypes with ancestry controls.\n3. For disease genetics: compatible cohort marker genotypes or a documented targeted query, genotype QC/PCs/kinship, and phenotype denominators or equivalent count data; exact published marker alleles/builds for replication.\n\n### Single next action with highest expected value\n\nDo not download either full VCF and do not run association tests. First pursue one focused provenance retrieval from the public pangenome source: obtain the event-level PAV/graph genotype resource (or a documented query for the five exact VariationIDs) together with its sample ID crosswalk. This resolves the most central ambiguity without spending compute on unrelated SNPs. If the source cannot provide those records, formally close the five-SV validation route and retain the candidates only as literature-prioritized markers. The existing 2026 cohort reconciliation and candidate evidence audit should remain a reproducibility/portfolio package, not be presented as a novel discovery paper by itself.\n\nThe accurate present description is: **five externally prioritized pearl millet SV association markers were audited against a multi-site downy mildew cohort; exact event identity and cohort genotypes remain unresolved, so no candidate-level disease association or climate-adaptation claim is made.**''')

# Source manifest
manifest=[]
for p in [PRIOR/'master_project_status.md', PRIOR/'five_sv_updated_evidence.tsv', PRIOR/'sv_event_definition_audit.tsv', PRIOR/'climate_feasibility.md', PRIOR/'climate_accession_coordinates.tsv', PRIOR/'climate_dataset_options.tsv', PRIOR/'genotype_retrieval_assessment.md', PRIOR/'gwas_feasibility_decision.md', PRIOR/'literature_evidence_matrix.tsv']:
    h=hashlib.sha256(p.read_bytes()).hexdigest()
    manifest.append([str(p),h,'Local prior audit; read-only reused input','2026-10-23'])
tsv('source_manifest.tsv',['source_path','sha256','provenance','access_date'],manifest)

# A reusable validator/packager for this output directory.
(OUT/'validate_task13.py').write_text('''#!/usr/bin/env python3\nfrom pathlib import Path\nimport csv, hashlib\nroot=Path(__file__).resolve().parent\nneed=["sv_recovery_results.tsv","sv_recovery_limitations.md","coordinate_provenance_audit.md","climate_variable_plan.tsv","climate_feasibility_decision.md","alternative_genetic_analysis_assessment.md","updated_literature_gap.md","research_direction_comparison.tsv","task13_final_recommendation.md","source_manifest.tsv","execution_log.txt"]\nmissing=[x for x in need if not (root/x).is_file()]\nassert not missing, f"missing deliverables: {missing}"\nwith (root/"sv_recovery_results.tsv").open(encoding="utf-8",newline="") as f: rows=list(csv.DictReader(f,delimiter="\\t"))\nassert len(rows)==5 and len({r["candidate_id"] for r in rows})==5\nassert all(r["definition_class"].startswith("3 - Only association-table") for r in rows)\nassert all(r["start_breakpoint"]=="Unknown/not reported" for r in rows)\nwith (root/"climate_variable_plan.tsv").open(encoding="utf-8",newline="") as f: climate=list(csv.DictReader(f,delimiter="\\t"))\nassert len(climate)>=8 and all(r["status"]=="Not extracted" for r in climate)\nprint(f"VALID: {len(need)} required deliverables; five unique candidates; no invented event calls; {len(climate)} climate variables marked not extracted.")\n''',encoding='utf-8')

write('execution_log.txt', f'''Task 13 execution log\nUTC package timestamp: {STAMP}\nProject: {PROJECT}\nPrior package: {PRIOR}\nActions: read prior master status, candidate event/evidence tables, climate feasibility, genotype retrieval assessment, GWAS decision, literature matrix and checksum manifest; reused audited records; generated decision tables and limitations; did not modify source data; did not download VCF or climate data; did not run GEA/GWAS; did not initialize Git.\nValidation: see validate_task13.py output and checksums.sha256.\n''')

subprocess = __import__('subprocess')
v=subprocess.run(['python3',str(OUT/'validate_task13.py')],capture_output=True,text=True,check=True)
with (OUT/'execution_log.txt').open('a',encoding='utf-8') as f: f.write(v.stdout)
checks=[]
for p in sorted(OUT.iterdir()):
    if p.is_file() and p.name!='checksums.sha256': checks.append(f"{hashlib.sha256(p.read_bytes()).hexdigest()}  {p.name}")
(OUT/'checksums.sha256').write_text('\n'.join(checks)+'\n',encoding='utf-8')
# Revalidate output checksums against files.
for line in (OUT/'checksums.sha256').read_text().splitlines():
    digest,name=line.split('  ',1)
    assert hashlib.sha256((OUT/name).read_bytes()).hexdigest()==digest
print(OUT)
